    code: function (DCLogic) {
class Component extends DCLogic {
  constructor(p){ super(p); this.state = { open: false }; }
  renderVals() {
    const s = this.state;
    const cats = ['Pisos e revestimentos', 'Louças e cubas', 'Metais sanitários', 'Iluminação', 'Tintas e acessórios', 'Elétrica', 'Hidráulica', 'Ferramentas'];
    const M = [{ label: 'Todas as categorias', href: 'Produtos.dc.html', fg: '#733635' }]
      .concat(cats.map((c) => ({ label: c, href: 'Produtos.dc.html', fg: '#1E1110' })))
      .concat([{ label: 'Ofertas', href: 'Produtos.dc.html', fg: '#FF6037' }, { label: 'Minha conta', href: 'MinhaConta.dc.html', fg: '#1E1110' }, { label: 'Venda para Empresas', href: 'VendaEmpresas.dc.html', fg: '#1E1110' }]);
    return {
      cats,
      allCur: (this.props.active ?? 'home') === 'produtos' ? 'page' : 'false',
      mlinks: M.map((m, i) => ({ ...m, delay: (100 + i * 40) + 'ms' })),
      open: s.open,
      openStr: s.open ? 'true' : 'false',
      menuLabel: s.open ? 'Fechar menu' : 'Abrir menu',
      toggle: () => this.setState({ open: !s.open }),
      l1top: s.open ? '21px' : '16px',
      l2top: s.open ? '21px' : '26px',
      l1rot: s.open ? 'rotate(45deg)' : 'rotate(0deg)',
      l2rot: s.open ? 'rotate(-45deg)' : 'rotate(0deg)'
    };
  }
}
;return Component; }
